/**
 * Shapes of the 2D body figure. The path data in paths.*.ts is generated by
 * scripts/vendor-body-figure.mjs.
 */

export type FigureSlug =
  | "abs"
  | "adductors"
  | "ankles"
  | "biceps"
  | "calves"
  | "chest"
  | "deltoids"
  | "feet"
  | "forearm"
  | "gluteal"
  | "hamstring"
  | "hands"
  | "hair"
  | "head"
  | "knees"
  | "lower-back"
  | "neck"
  | "obliques"
  | "quadriceps"
  | "tibialis"
  | "trapezius"
  | "triceps"
  | "upper-back";

/** Anatomical side: the body's own left and right, not the viewer's. */
export type FigureSide = "left" | "right" | "center";

export type FigureViewName = "front" | "back";

export type FigureGender = "male" | "female";

/** [minX, minY, maxX, maxY] in viewBox units. */
export type FigureBBox = [number, number, number, number];

export interface FigureShape {
  slug: FigureSlug;
  side: FigureSide;
  /** SVG path strings. Kept separate; do not concatenate. */
  paths: string[];
  bbox: FigureBBox;
}

export interface FigureView {
  /** [x, y, width, height] */
  viewBox: [number, number, number, number];
  outline: string;
  shapes: FigureShape[];
}

export interface FigureData {
  front: FigureView;
  back: FigureView;
}
